WITH valid_web_events AS (SELECT * FROM web_events WHERE session_id IN (4, 27) AND (duration_sec < 335 OR duration_sec != 445)), Summary AS (SELECT page, session_id, MAX(duration_sec) max_duration_sec, MAX(event_time) last_event_time FROM valid_web_events GROUP BY page, session_id) SELECT page, session_id, max_duration_sec, last_event_time FROM Summary ORDER BY last_event_time, page, session_id LIMIT 1
